# HMAC secret used for HS256 tokens
HMAC_SECRET = os.urandom(32)

ALLOWED_ALGORITHMS = ["HS256", "RS256"]

def base64url_decode(data: str) -> bytes:
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data.encode('utf-8'))

def base64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')

def create_token(payload: Dict[str, Any], algorithm: str = "HS256") -> str:
    header = {"alg": algorithm, "typ": "JWT"}
    header_encoded = base64url_encode(json.dumps(header, separators=(',', ':')).encode())
    payload_encoded = base64url_encode(json.dumps(payload, separators=(',', ':')).encode())
    signing_input = f"{header_encoded}.{payload_encoded}"

    if algorithm == "HS256":
        signature = hmac.new(HMAC_SECRET, signing_input.encode(), hashlib.sha256).digest()
    else:
        raise ValueError(f"Signing with {algorithm} not implemented in this demo")

    signature_encoded = base64url_encode(signature)
    return f"{signing_input}.{signature_encoded}"

