class TokenValidator:
    def __init__(self, hmac_secret: bytes, rsa_public_key: bytes, allowed_algorithms: list):
        self._hmac_secret = hmac_secret
        self._rsa_public_key = rsa_public_key
        self._allowed_algorithms = allowed_algorithms
        self._revoked_jti = set()

    def revoke_token(self, jti: str):
        self._revoked_jti.add(jti)

    def _decode_parts(self, token: str) -> tuple:
        parts = token.split('.')
        if len(parts) != 3:
            raise ValueError("Invalid token format")
        return parts[0], parts[1], parts[2]

    def _parse_header(self, header_b64: str) -> Dict[str, Any]:
        try:
            header_bytes = base64url_decode(header_b64)
            header = json.loads(header_bytes)
        except (json.JSONDecodeError, Exception) as e:
            raise ValueError(f"Invalid header: {e}")
        if not isinstance(header, dict):
            raise ValueError("Header must be a JSON object")
        return header

    def _parse_payload(self, payload_b64: str) -> Dict[str, Any]:
        try:
            payload_bytes = base64url_decode(payload_b64)
            payload = json.loads(payload_bytes)
        except (json.JSONDecodeError, Exception) as e:
            raise ValueError(f"Invalid payload: {e}")
        if not isinstance(payload, dict):
            raise ValueError("Payload must be a JSON object")
        return payload

    def _get_verification_key(self, algorithm: str) -> Optional[bytes]:
        """Get the appropriate key material for the given algorithm."""
        if algorithm == "HS256":
            return self._hmac_secret
        elif algorithm == "RS256":
            return self._rsa_public_key
        else:
            return None

    def _verify_signature_internal(self, algorithm: str, signing_input: str, signature: bytes, key: bytes) -> bool:
        """Verify signature using the specified algorithm and key."""
        if algorithm == "HS256":
            expected = hmac.new(key, signing_input.encode(), hashlib.sha256).digest()
            return hmac.compare_digest(expected, signature)
        elif algorithm == "RS256":
            # Production RSA verification
            return False
        else:
            return False

    def validate_token(self, token: str) -> Optional[Dict[str, Any]]:
        """Validate a JWT token and return the payload if valid.

        Security: Checks algorithm against allowlist FIRST, then selects
        verification method based on the validated algorithm, verifies signature,
        validates expiration and revocation status.
        """
        try:
            header_b64, payload_b64, signature_b64 = self._decode_parts(token)
            header = self._parse_header(header_b64)

            # Check algorithm is allowed BEFORE selecting verification method
            declared_alg = header.get("alg", "")
            if declared_alg not in self._allowed_algorithms:
                return None

            # Get key material based on validated algorithm
            key_material = self._get_verification_key(declared_alg)
            if key_material is None:
                return None

            # Verify signature using the validated algorithm
            signing_input = f"{header_b64}.{payload_b64}"
            signature = base64url_decode(signature_b64)

            if not self._verify_signature_internal(declared_alg, signing_input, signature, key_material):
                return None

            # Parse and validate payload
            payload = self._parse_payload(payload_b64)

            # Check expiration
            if "exp" in payload:
                if time.time() > payload["exp"]:
                    return None

            # Check revocation
            if "jti" in payload:
                if payload["jti"] in self._revoked_jti:
                    return None

            return payload

        except (ValueError, KeyError, TypeError):
            return None


class AuthMiddleware:
    def __init__(self, validator: TokenValidator):
        self._validator = validator
        self._rate_limits: Dict[str, list] = {}

    def _check_rate_limit(self, user_id: str) -> bool:
        now = time.time()
        if user_id not in self._rate_limits:
            self._rate_limits[user_id] = []

        # Clean old entries
        self._rate_limits[user_id] = [t for t in self._rate_limits[user_id] if now - t < 60]

        if len(self._rate_limits[user_id]) >= 100:
            return False

        self._rate_limits[user_id].append(now)
        return True

    def authenticate_request(self, authorization_header: Optional[str]) -> Optional[Dict[str, Any]]:
        if not authorization_header:
            return None

        if not authorization_header.startswith("Bearer "):
            return None

        token = authorization_header[7:]
        if not token or len(token) > 8192:
            return None

        payload = self._validator.validate_token(token)
        if payload is None:
            return None

        user_id = payload.get("sub")
        if not user_id or not isinstance(user_id, str):
            return None

        if not self._check_rate_limit(user_id):
            return None

        return payload


def get_user_profile(auth_header: str, validator: TokenValidator) -> Dict[str, Any]:
    middleware = AuthMiddleware(validator)
    payload = middleware.authenticate_request(auth_header)

    if payload is None:
        return {"error": "Unauthorized", "status": 401}

    return {
        "user_id": payload.get("sub"),
        "email": payload.get("email"),
        "roles": payload.get("roles", []),
        "status": 200
    }


